{
  "requirement_id": "REQ-006",
  "cases": [
    {
      "id": "TC-1",
      "title": "Assign task to a non-project member returns 422 and keeps assignee unchanged",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task 1\"} as alice",
        "PATCH /api/tasks/{tid} with {\"assignee_id\": bob_id} as alice"
      ],
      "expected": "指派對象必須是該專案成員；否則回傳 422 狀態碼，且任務的 assignee 維持不變。"
    },
    {
      "id": "TC-2",
      "title": "Assign task to a non-existent user returns 422",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project B\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task 2\"} as alice",
        "PATCH /api/tasks/{tid} with {\"assignee_id\": 99999} as alice"
      ],
      "expected": "指派不存在的使用者時，回傳 422 狀態碼。"
    }
  ]
}

